/**
 * The reader of the solved raise-defence tables (HorseHoldemTournamentRaiseDefenceSolved.data.ts, generated by
 * server/scripts/holdem-tournament-raise-defence-solve/solve.py: the chip-EV equilibrium of the open / defend /
 * re-raise game, heads-up and three-or-more-handed with a simplified behind-player model; see the script header).
 *
 * A spot is a kind ('hu', or 'ring:<players behind the opener: 1 | 2 | 3 | 5>:<the defender: sb | bb>'), the effective
 * depth in big blinds, the open size in big blinds and the dead ante in big blinds. A query between grid points is
 * the weighted mix of the surrounding solved spots (linear in depth, open size and ante, each clamped to the grid):
 * a mix of two equilibrium strategies of neighbouring games, not itself solved. Nothing here draws a random number.
 */
import { inflateSync } from 'node:zlib';
import {
  HOLDEM_RAISE_DEFENCE_REALISATION,
  HOLDEM_RAISE_DEFENCE_SOLVED_GRID,
  HOLDEM_RAISE_DEFENCE_SOLVED_INDEX_JSON,
  HOLDEM_RAISE_DEFENCE_SOLVED_ORDER,
  HOLDEM_RAISE_DEFENCE_SOLVED_VERSION,
  HOLDEM_RAISE_DEFENCE_SOLVED_WORST_GAIN_BB,
  HOLDEM_RAISE_DEFENCE_SOLVED_Z64,
  type SolvedSpotIndex,
} from './HorseHoldemTournamentRaiseDefenceSolved.data.js';

export {
  HOLDEM_RAISE_DEFENCE_SOLVED_VERSION,
  HOLDEM_RAISE_DEFENCE_SOLVED_WORST_GAIN_BB,
  HOLDEM_RAISE_DEFENCE_SOLVED_ORDER,
  HOLDEM_RAISE_DEFENCE_REALISATION,
};

/** Every node's actions, fold first (the stored bytes omit fold: fold = the rest). */
export const SOLVED_NODE_ACTIONS = {
  o_root: ['fold', 'open', 'jam'],
  d_vs_open: ['fold', 'call', 'three_bet', 'jam'],
  o_vs_jam: ['fold', 'call'],
  o_vs_3bet: ['fold', 'call', 'four_bet', 'jam'],
  d_vs_jam_3bet: ['fold', 'call'],
  d_vs_4bet: ['fold', 'jam'],
  o_vs_jam_4bet: ['fold', 'call'],
} as const;
export type SolvedNodeName = keyof typeof SOLVED_NODE_ACTIONS;

let BYTES: Buffer | null = null;
const bytes = (): Buffer =>
  (BYTES ??= inflateSync(Buffer.from(HOLDEM_RAISE_DEFENCE_SOLVED_Z64, 'base64')));

/**
 * The spot index, parsed once at module load from the JSON text of the data module (a string, not an object literal:
 * the engine image build parses every source under a 1 GB heap) and checked against the grid it claims.
 */
export const HOLDEM_RAISE_DEFENCE_SOLVED_INDEX: readonly SolvedSpotIndex[] = (() => {
  const index = JSON.parse(HOLDEM_RAISE_DEFENCE_SOLVED_INDEX_JSON) as SolvedSpotIndex[];
  const G = HOLDEM_RAISE_DEFENCE_SOLVED_GRID;
  const want = (1 + G.ring.length) * G.depths.length * G.opens.length * G.antes.length;
  if (!Array.isArray(index) || index.length !== want)
    throw new Error(`raise defence solved index: ${index?.length} spots, the grid has ${want}`);
  for (const s of index)
    if (
      typeof s.kind !== 'string' ||
      !Number.isFinite(s.S) ||
      !s.nodes ||
      !Number.isFinite(s.offset)
    )
      throw new Error('raise defence solved index: a malformed spot');
  return Object.freeze(index);
})();
const BY_KEY = new Map<string, SolvedSpotIndex>();
for (const s of HOLDEM_RAISE_DEFENCE_SOLVED_INDEX) BY_KEY.set(`${s.kind}|${s.S}|${s.o}|${s.A}`, s);

/** The solved kind of a spot: heads-up with two dealt; else the opener's players behind (4 or more read as 5). */
export function solvedKind(dealt: number, openerBehind: number, defender: 'sb' | 'bb'): string {
  if (dealt <= 2) return 'hu';
  const b = Math.max(1, Math.round(openerBehind));
  const k = b <= 1 ? 1 : b === 2 ? 2 : b === 3 ? 3 : 5;
  return k === 1 ? 'ring:1:bb' : `ring:${k}:${defender}`;
}

export interface SolvedQuery {
  kind: string;
  depthBB: number;
  openBB: number;
  anteBB: number;
}

export interface SolvedNode {
  node: SolvedNodeName;
  actions: readonly string[];
  /** p[a][class]: the probability of action a (SOLVED_NODE_ACTIONS order) for each of the 169 classes. */
  p: Float64Array[];
  /** Action values (big blinds, from the start of the hand) of the stored non-all-in re-raises, where present. */
  q: Partial<Record<'three_bet' | 'four_bet', Float64Array>>;
  /** The epsilon-forced average of a rarely used action (the range the opponent's reply to it answers), where stored. */
  forced: Partial<Record<'open' | 'three_bet' | 'four_bet', Float64Array>>;
  /** The fixed players' jam-over-open and call-of-a-jam shares (ring kinds), null heads-up. */
  fixed: readonly [number, number] | null;
  /** The worst best-response gain (bb per hand) of the surrounding solved spots. */
  gain: number;
}

const bracket = (grid: readonly number[], x: number): Array<[number, number]> => {
  const v = Number.isFinite(x) ? Math.max(grid[0], Math.min(grid[grid.length - 1], x)) : grid[0];
  for (let i = 1; i < grid.length; i++)
    if (v <= grid[i]) {
      const t = (v - grid[i - 1]) / (grid[i] - grid[i - 1]);
      return t <= 0
        ? [[grid[i - 1], 1]]
        : t >= 1
          ? [[grid[i], 1]]
          : [
              [grid[i - 1], 1 - t],
              [grid[i], t],
            ];
    }
  return [[grid[grid.length - 1], 1]];
};

/** The node's strategy at a query (the weighted mix of the surrounding solved spots); null where no spot has it. */
export function solvedNode(query: SolvedQuery, node: SolvedNodeName): SolvedNode | null {
  const G = HOLDEM_RAISE_DEFENCE_SOLVED_GRID;
  const acts = SOLVED_NODE_ACTIONS[node];
  const p = acts.map(() => new Float64Array(169));
  const q: SolvedNode['q'] = {};
  const forced: SolvedNode['forced'] = {};
  let wsum = 0;
  let gain = 0;
  let fixedJo = 0;
  let fixedJc = 0;
  let fixedW = 0;
  const buf = bytes();
  for (const [S, ws] of bracket(G.depths, query.depthBB))
    for (const [o, wo] of bracket(G.opens, query.openBB))
      for (const [A, wa] of bracket(G.antes, query.anteBB)) {
        const spot = BY_KEY.get(`${query.kind}|${S}|${o}|${A}`);
        const nd = spot?.nodes[node];
        if (!spot || !nd) continue;
        const w = ws * wo * wa;
        wsum += w;
        gain = Math.max(gain, spot.gainO, spot.gainD);
        if (spot.fixed) {
          fixedJo += w * spot.fixed[0];
          fixedJc += w * spot.fixed[1];
          fixedW += w;
        }
        const stored = nd.actions;
        for (let c = 0; c < 169; c++) {
          let rest = 1;
          for (let k = 0; k < stored.length; k++) {
            const b = buf[nd.at + k * 169 + c];
            const v = b === 255 ? 1 : b / 256;
            rest -= v;
            p[acts.indexOf(stored[k] as never)][c] += w * v;
          }
          p[0][c] += w * Math.max(0, rest);
        }
        for (const a of ['open', 'three_bet', 'four_bet'] as const) {
          const at = nd[`f_${a}`];
          if (at === undefined) continue;
          const arr = (forced[a] ??= new Float64Array(169));
          for (let c = 0; c < 169; c++) {
            const b = buf[at + c];
            arr[c] += w * (b === 255 ? 1 : b / 256);
          }
        }
        for (const a of ['three_bet', 'four_bet'] as const) {
          const at = nd[`q_${a}`];
          if (at === undefined) continue;
          const arr = (q[a] ??= new Float64Array(169));
          for (let c = 0; c < 169; c++) arr[c] += w * (buf.readInt16LE(at + 2 * c) / 100);
        }
      }
  if (!(wsum > 0)) return null;
  for (const arr of p) for (let c = 0; c < 169; c++) arr[c] /= wsum;
  for (const arr of Object.values(q)) for (let c = 0; c < 169; c++) arr![c] /= wsum;
  for (const arr of Object.values(forced)) for (let c = 0; c < 169; c++) arr![c] /= wsum;
  return {
    node,
    actions: acts,
    p,
    q,
    forced,
    fixed: fixedW > 0 ? [fixedJo / fixedW, fixedJc / fixedW] : null,
    gain,
  };
}

/** The range a reply to `action` answers: its epsilon-forced average where stored, else its column. */
export function solvedRangeOf(
  n: SolvedNode,
  action: 'open' | 'three_bet' | 'four_bet'
): Float64Array {
  return n.forced[action] ?? solvedAction(n, action);
}

/** One action's column of a node (class weights 0..1). */
export function solvedAction(n: SolvedNode, action: string): Float64Array {
  const i = n.actions.indexOf(action);
  return i >= 0 ? n.p[i] : new Float64Array(169);
}

/** The out-of-position player's realised share of a postflop pot (the measured line, clipped to [0, 1]). */
export function realisedShareOutOfPosition(equity: number, spr: number): number {
  const R = HOLDEM_RAISE_DEFENCE_REALISATION;
  const xs = R.sprCentres;
  const x = Number.isFinite(spr) ? Math.max(0, spr) : xs[xs.length - 1];
  const at = (ys: readonly number[]): number => {
    if (x <= xs[0]) return ys[0];
    for (let i = 1; i < xs.length; i++)
      if (x <= xs[i])
        return ys[i - 1] + ((x - xs[i - 1]) / (xs[i] - xs[i - 1])) * (ys[i] - ys[i - 1]);
    return ys[ys.length - 1];
  };
  return Math.max(0, Math.min(1, at(R.a) + at(R.b) * equity));
}

/**
 * The range of a jam the all-in call price meets, from the solved tables (used by holdemTournamentAllInCallIsPriced
 * only while one of the three raise-defence options is on): raiseIndex 2 a jam over the open (the defender's jam),
 * 3 the opener's jam over a 3-bet, 4 the 3-bettor's jam over a 4-bet. Null where the tables do not reach.
 */
export function solvedJamRange(args: {
  dealt: number;
  raiseIndex: number;
  openerBehind: number;
  /** The defender's (the 3-bettor's) blind: 'bb' when he is the big blind, else 'sb'. */
  defender: 'sb' | 'bb';
  depthBB: number;
  openBB: number;
  anteBB: number;
}): Float64Array | null {
  if (!(args.depthBB > 0) || args.depthBB > HOLDEM_RAISE_DEFENCE_SOLVED_GRID.depths.at(-1)!)
    return null;
  const query: SolvedQuery = {
    kind: solvedKind(args.dealt, args.openerBehind, args.defender),
    depthBB: args.depthBB,
    openBB: args.openBB,
    anteBB: args.anteBB,
  };
  const mul = (a: Float64Array, b: Float64Array): Float64Array => a.map((x, i) => x * b[i]);
  if (args.raiseIndex === 2) {
    const d = solvedNode(query, 'd_vs_open');
    return d ? Float64Array.from(solvedAction(d, 'jam')) : null;
  }
  if (args.raiseIndex === 3) {
    const r = solvedNode(query, 'o_root');
    const v = solvedNode(query, 'o_vs_3bet');
    return r && v ? mul(solvedAction(r, 'open'), solvedAction(v, 'jam')) : null;
  }
  if (args.raiseIndex === 4) {
    const d = solvedNode(query, 'd_vs_open');
    const v = solvedNode(query, 'd_vs_4bet');
    return d && v ? mul(solvedAction(d, 'three_bet'), solvedAction(v, 'jam')) : null;
  }
  return null;
}
